patch_result.patch:
--- a/libredwg/src/in_json.c
+++ b/libredwg/src/in_json.c
@@ -1193,6 +1193,7 @@
       else if (t->type == JSMN_PRIMITIVE
                && (strEQc (f->type, "BD") || strEQc (f->type, "RD")))
         {
+          if (f->size != sizeof (double)) { LOG_WARN ("HEADER.%s size mismatch for %s: %u != %zu", key, f->type, f->size, sizeof (double)); json_advance_unknown (dat, tokens, t->type, 0); continue; }
           double num = json_float (dat, tokens);
           LOG_TRACE ("%s: " FORMAT_RD " [%s]\n", key, num, f->type)
           dwg_dynapi_header_set_value (dwg, key, &num, 0);
@@ -1204,6 +1205,7 @@
                    || strEQc (f->type, "BL") || strEQc (f->type, "RSd")
                    || strEQc (f->type, "BLd") || strEQc (f->type, "BSd")))
         {
+          if (f->size > sizeof (long)) { LOG_WARN ("HEADER.%s size mismatch for %s: %u > %zu", key, f->type, f->size, sizeof (long)); json_advance_unknown (dat, tokens, t->type, 0); continue; }
           long num = json_long (dat, tokens);
           LOG_TRACE ("%s: %ld [%s]\n", key, num, f->type)
           dwg_dynapi_header_set_value (dwg, key, &num, 0);
@@ -1211,6 +1213,7 @@
       else if (t->type == JSMN_PRIMITIVE
                && (strEQc (f->type, "RLL") || strEQc (f->type, "BLL")))
         {
+          if (f->size != sizeof (uint64_t)) { LOG_WARN ("HEADER.%s size mismatch for %s: %u != %zu", key, f->type, f->size, sizeof (uint64_t)); json_advance_unknown (dat, tokens, t->type, 0); continue; }
           uint64_t num = json_longlong (dat, tokens);
           LOG_TRACE ("%s: " FORMAT_RLL " [%s]\n", key, num, f->type)
           dwg_dynapi_header_set_value (dwg, key, &num, 0);
@@ -1220,6 +1223,7 @@
         {
           size_t len;
           char *str = json_string (dat, tokens);
+          if (f->size != sizeof (char *)) { LOG_WARN ("HEADER.%s size mismatch for %s: %u != %zu", key, f->type, f->size, sizeof (char *)); free (str); continue; }
           LOG_TRACE ("%s: \"%s\" [%s]\n", key, str, f->type);
           if (dwg->header.version < R_13b1 && strEQc (key, "MENU")
               && (len = strlen (str) > 15))

